import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Comparaison Blockly, couleurs et fonctions","description":"","frontmatter":{"title":"Comparaison Blockly, couleurs et fonctions"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/blockly-audit.md","filePath":"fr/projects/blocks-for-ha/blockly-audit.md","lastUpdated":1792852622000}'),r={name:"fr/projects/blocks-for-ha/blockly-audit.md"};function n(i,e,l,c,u,d){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="comparaison-blockly-couleurs-et-fonctions" tabindex="-1">Comparaison Blockly, couleurs et fonctions <a class="header-anchor" href="#comparaison-blockly-couleurs-et-fonctions" aria-label="Permalink to &quot;Comparaison Blockly, couleurs et fonctions&quot;">​</a></h1><p>Les exemples ioBroker servent de référence d’usage ; les blocs produisent des structures <strong>HA/YAML et Jinja</strong>. Le JavaScript ioBroker n’est pas transféré comme moteur d’exécution.</p><h2 id="couverture-et-adaptations" tabindex="-1">Couverture et adaptations <a class="header-anchor" href="#couverture-et-adaptations" aria-label="Permalink to &quot;Couverture et adaptations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Groupe</th><th>Adaptation</th></tr></thead><tbody><tr><td>Logique</td><td>Comparaisons, ET/OU/NON, booléens, null, choix de valeur, branches, cas, intervalle et valeur de secours.</td></tr><tr><td>Boucles</td><td>Répétition, tant que/jusqu’à, pour chaque élément, compteur et boucle avec variable nommée.</td></tr><tr><td>Mathématiques</td><td>Calculs, propriétés, constantes, trigonométrie et atan2, arrondis, statistiques, modulo, limitation, aléatoire.</td></tr><tr><td>Textes</td><td>Multiligne, sauts de ligne, assemblage, recherche, extraction, casse, suppression d’espaces, comptage, remplacement et inversion.</td></tr><tr><td>Listes</td><td>Création, répétition, lecture, copie, modification immuable, découpage/assemblage, tri et inversion.</td></tr><tr><td>Couleurs</td><td>Sélecteur, RGB en pourcentages, aléatoire, mélange et action de lampe.</td></tr><tr><td>Variables et fonctions</td><td>Variables HA pendant l’exécution ; fonctions de valeur Blockly développées en Jinja.</td></tr><tr><td>HA</td><td>Déclencheurs, entités, scripts, assistants, journal, mises à jour, actions génériques et modèles.</td></tr></tbody></table><p>Opérations ajoutées au-delà des captures ioBroker : notamment atan2, inversion du texte, attente avec expiration et fonctions de valeur avec paramètres. Le catalogue recense les <strong>111 types</strong> ; les variantes de menus déroulants ne sont pas des types supplémentaires.</p><p>Des adaptations ne sont pas disponibles comme équivalents directs : <code>break</code>/<code>continue</code> ciblés, fonctions contenant des actions ou récursion, invites navigateur à l’exécution HA, intervalles ioBroker nommés, JSONata sans moteur HA. Un <code>stop</code> termine tout le scénario et ne doit pas être décrit comme une simple rupture de boucle.</p><h2 id="couleurs" tabindex="-1">Couleurs <a class="header-anchor" href="#couleurs" aria-label="Permalink to &quot;Couleurs&quot;">​</a></h2><p>RGB : pourcentages limités à 0–100, convertis en canaux 0–255. Rouge 100, vert 50, bleu 0 donne <code>[255,128,0]</code>. Mélange : part 0 pour la première couleur et 1 pour la seconde ; rouge/bleu à 0,5 donne <code>[128,0,128]</code>. Mélange linéaire sans correction gamma.</p><p>La couleur aléatoire crée trois canaux à chaque évaluation. L’action de lampe produit <code>light.turn_on</code> avec la couleur et une luminosité en pourcentage. La lampe doit prendre en charge ces options.</p><h2 id="fonctions-d-action-et-retours-conditionnels-depuis-0-1-47" tabindex="-1">Fonctions d’action et retours conditionnels depuis 0.1.47 <a class="header-anchor" href="#fonctions-d-action-et-retours-conditionnels-depuis-0-1-47" aria-label="Permalink to &quot;Fonctions d’action et retours conditionnels depuis 0.1.47&quot;">​</a></h2><p>Dans <strong>Fonctions</strong>, placer une définition d’action à côté de l’automatisation. Saisir un nom valide sans espaces, ajouter jusqu’à huit paramètres ASCII distincts via l’engrenage et insérer les actions HA dans le corps. Le bloc d’appel apparaît automatiquement ; connecter tous les arguments. Lire les paramètres avec des blocs de variable de <strong>Variables</strong>, par exemple pour un message de journal, une pause ou une affectation.</p><p>L’export produit une <code>sequence</code> HA native. Chaque appel reçoit ses propres variables internes de paramètre ; les arguments sont évalués lors de l’appel. Les appels imbriqués sont possibles, sans récursion ni corps vide. Les paramètres ne remplacent pas les variables HA de même nom. Les autres affectations restent des affectations HA ordinaires. Les champs de texte Jinja/JSON gardent leur contexte HA normal et ne sont pas réécrits pour les paramètres locaux ; utiliser les blocs de variable. <strong>Stop</strong> arrête toujours toute l’exécution HA.</p><p><strong>Si / renvoyer / sinon</strong> produit une valeur Jinja conditionnelle. Seule la branche sélectionnée est évaluée. Relier ce bloc à la sortie d’une fonction de valeur ou à une autre entrée de valeur. Condition et deux branches sont requises. Ce n’est pas un retour anticipé d’une suite d’actions.</p><p>Les projets JSON conservent définitions, paramètres, appels et disposition. Le YAML contient les étapes ou expressions développées ; sa réimportation reconstruit ces étapes, sans recréer les définitions de fonction. <a href="./blocks#fonctions-depuis-0-1-47">Images des blocs</a>.</p><h2 id="fonctions-de-valeur" tabindex="-1">Fonctions de valeur <a class="header-anchor" href="#fonctions-de-valeur" aria-label="Permalink to &quot;Fonctions de valeur&quot;">​</a></h2><p>L’éditeur natif Blockly définit une fonction avec valeur de retour. L’engrenage modifie jusqu’à <strong>8 paramètres</strong>. Les noms doivent être des identifiants ASCII valides et distincts. Les appels apparaissent dynamiquement dans Fonctions et leurs entrées suivent les paramètres.</p><p>À l’export, l’expression de retour est développée en Jinja, avec liaison locale des paramètres. Pas d’action ni récursion. Définition manquante/ambiguë, retour absent, argument absent ou excès de paramètres empêchent l’export. Un accès à une variable dans une fonction lit le paramètre local s’il existe, sinon la variable HA.</p><h2 id="sources-originales" tabindex="-1">Sources originales <a class="header-anchor" href="#sources-originales" aria-label="Permalink to &quot;Sources originales&quot;">​</a></h2><p><a href="https://github.com/RaspberryPiFoundation/blockly" target="_blank" rel="noreferrer">Blockly</a> · <a href="https://github.com/RaspberryPiFoundation/blockly/tree/develop/blocks" target="_blank" rel="noreferrer">Blocs standard</a> · <a href="https://github.com/raspberrypifoundation/blockly-samples" target="_blank" rel="noreferrer">Blockly samples et plugins</a> · <a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noreferrer">ioBroker JavaScript</a> · <a href="https://www.home-assistant.io/docs/configuration/templating/" target="_blank" rel="noreferrer">Modèles HA</a>.</p><p>Les extensions d’origine sont liées individuellement dans le <a href="./blocks">catalogue</a>. Les notices de licence restent incluses dans l’application.</p>',20)])])}const b=t(r,[["render",n]]);export{m as __pageData,b as default};
